{
  "name": "@sonic182/graphmem",
  "version": "0.15.2",
  "mcpName": "io.github.sonic182/graphmem",
  "description": "Shared local memory for coding agents with semantic recall, knowledge graph, and code navigation.",
  "keywords": ["pi-package", "opencode-plugin", "mcp", "memory", "knowledge", "development", "coding-agent", "agent-memory", "semantic-search", "knowledge-graph"],
  "license": "MIT",
  "publishConfig": { "access": "public" },
  "type": "module",
  "main": "./plugin/opencode/index.js",
  "files": ["plugin/", "scripts/gmem.js", "scripts/graphmem.js", "scripts/npm-install.js", "scripts/binary.js", "docs/", "!docs/assets/", "README.md", "LICENSE"],
  "bin": {
    "gmem": "scripts/gmem.js",
    "graphmem": "scripts/graphmem.js",
    "gmem-install": "scripts/npm-install.js"
  },
  "scripts": {
    "test": "node --test"
  },
  "engines": { "node": ">=18" },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-coding-agent": { "optional": true }
  },
  "exports": {
    ".": "./plugin/opencode/index.js",
    "./server": "./plugin/opencode/index.js"
  },
  "homepage": "https://github.com/sonic182/graphmem",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/sonic182/graphmem.git"
  },
  "pi": {
    "image": "https://raw.githubusercontent.com/sonic182/graphmem/master/docs/assets/graphmem-banner.png",
    "skills": ["./plugin/skills"],
    "extensions": ["./plugin/pi/extensions"]
  }
}
